#!/usr/bin/env node
/**
 * Tests for glued PowerShell heads (`$r=sqlcmd`, `$r=(sqlcmd`, `[void](sqlcmd`, `if($x){sqlcmd`): a raw
 * database client there is a command head, so sql-target denies it on a non-dev host.
 *
 *   node --test tools/guard-shell-glued-heads.test.mjs
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const { evaluate } = require(join(ROOT, 'hooks', 'lib', 'guard.js'));
const { commandPositions } = require(join(ROOT, 'hooks', 'lib', 'shell-parse.js'));

const run = (command) => evaluate({ tool_name: 'PowerShell', tool_input: { command }, cwd: ROOT, session_id: 's' });

const GLUED = [
  '$r=sqlcmd -S prod.example.com -Q "select 1"',
  '$r=(sqlcmd -S prod.example.com -Q "select 1")',
  '$r = @(sqlcmd -S prod.example.com -Q "select 1")',
  '[void](sqlcmd -S prod.example.com -Q x)',
  'if($true){sqlcmd -S prod.example.com -Q x}',
  'foreach($i in 1){sqlcmd -S prod.example.com -Q x}',
  '$r = sqlcmd -S prod.example.com -Q x',
];

for (const command of GLUED) {
  test(`given the PowerShell line ${command}, when guard evaluates it, then it is denied for a non-dev host`, () => {
    // Given
    const line = command;

    // When
    const result = run(line);

    // Then
    assert.equal(result?.decision, 'deny');
  });

  test(`given the PowerShell line ${command}, when commandPositions runs, then sqlcmd is a command head`, () => {
    // Given
    const line = command;

    // When
    const heads = commandPositions(line).map((tokens) => tokens[0]);

    // Then
    assert.ok(heads.includes('sqlcmd'), JSON.stringify(heads));
  });
}

test('given a glued assignment of a local sqlcmd call, when guard evaluates it, then it is not denied', () => {
  // Given
  const line = '$r=sqlcmd -S localhost -Q "select 1"';

  // When
  const result = run(line);

  // Then
  assert.notEqual(result?.decision, 'deny');
});
